interface Greeter {
    fun name(): String

    fun greet(): String {
        return "Hello, " + name()
    }
}

class Ada : Greeter {
    override fun name(): String {
        return "Ada"
    }
}

class Robot : Greeter {
    override fun name(): String {
        return "Robot"
    }

    override fun greet(): String {
        return "Beep, " + name()
    }
}

fun main() {
    println(Ada().greet())
    println(Robot().greet())
}

